      0.00
    </span>
  </div>

  <!-- Botón verificar -->
  <button id="btn-verificar"
    style="padding:8px 18px; background:#437a22; color:#fff; border:none;
           border-radius:6px; font-size:14px; cursor:pointer; margin-bottom:14px;">
    ✅ Verificar mi respuesta
  </button>

  <!-- Panel de resultado -->
  <div id="panel-resultado"
    style="padding:12px 16px; background:#f3f0ec; border-radius:8px;
           font-size:13px; color:#7a7974; margin-bottom:14px; min-height:42px;">
    Ajusta el slider y pulsa <strong>✅ Verificar</strong> para ver tu puntuación.
  </div>

  <!-- Historial -->
  <div id="historial-wrap" style="display:none;">
    <table id="tabla-historial"
      style="border-collapse:collapse; width:100%; font-size:13px;">
      <thead>
        <tr style="background:#edeae5;">
          <th style="padding:6px 10px; text-align:center;">#</th>
          <th style="padding:6px 10px; text-align:center;">r real</th>
          <th style="padding:6px 10px; text-align:center;">Estimación</th>
          <th style="padding:6px 10px; text-align:center;">Diferencia</th>
          <th style="padding:6px 10px; text-align:center;">Evaluación</th>
        </tr>
      </thead>
      <tbody id="tabla-body"></tbody>
    </table>
    <div id="resumen-stats"
      style="text-align:right; font-size:13px; color:#555; margin-top:6px;"></div>
  </div>
</div>

<script>
(function () {
  // ── Utilidades ──────────────────────────────────────────────────────────────
  function rnorm(n) {
    const out = [];
    for (let i = 0; i < n; i += 2) {
      const u1 = Math.random() + 1e-12, u2 = Math.random();
      const mag = Math.sqrt(-2 * Math.log(u1));
      out.push(mag * Math.cos(2 * Math.PI * u2));
      if (i + 1 < n) out.push(mag * Math.sin(2 * Math.PI * u2));
    }
    return out;
  }

  function generateCloud(rho, n) {
    const z1 = rnorm(n), z2 = rnorm(n);
    const raw = z1.map((v, i) => ({
      x: v,
      y: rho * v + Math.sqrt(Math.max(0, 1 - rho * rho)) * z2[i]
    }));
    const xMin = Math.min(...raw.map(p => p.x));
    const xMax = Math.max(...raw.map(p => p.x));
    const yMin = Math.min(...raw.map(p => p.y));
    const yMax = Math.max(...raw.map(p => p.y));
    return raw.map(p => ({
      x: 40  + ((p.x - xMin) / (xMax - xMin + 1e-9)) * 160,
      y: 250 + ((p.y - yMin) / (yMax - yMin + 1e-9)) * 350
    }));
  }

  function pearson(pts) {
    const n = pts.length;
    const mx = pts.reduce((s, p) => s + p.x, 0) / n;
    const my = pts.reduce((s, p) => s + p.y, 0) / n;
    let sxy = 0, sx2 = 0, sy2 = 0;
    pts.forEach(p => {
      sxy += (p.x - mx) * (p.y - my);
      sx2 += (p.x - mx) ** 2;
      sy2 += (p.y - my) ** 2;
    });
    return sxy / Math.sqrt(sx2 * sy2 + 1e-12);
  }

  // ── Estado ──────────────────────────────────────────────────────────────────
  const STEPS = Array.from({ length: 39 }, (_, i) =>
    Math.round((-0.95 + i * 0.05) * 100) / 100
  );

  let currentCloud = null;
  let currentRhoReal = 0;
  let historial = [];

  // ── Referencias DOM ─────────────────────────────────────────────────────────
  const canvas   = document.getElementById("corr-canvas");
  const ctx      = canvas.getContext("2d");
  const slider   = document.getElementById("slider-r");
  const sliderVal= document.getElementById("slider-val");
  const btnNuevo = document.getElementById("btn-nuevo");
  const btnVer   = document.getElementById("btn-verificar");
  const panelRes = document.getElementById("panel-resultado");
  const histWrap = document.getElementById("historial-wrap");
  const tablaBody= document.getElementById("tabla-body");
  const resStats = document.getElementById("resumen-stats");

  // ── Dibujar ─────────────────────────────────────────────────────────────────
  const W = canvas.width, H = canvas.height;
  const mg = { top: 28, right: 18, bottom: 50, left: 56 };
  const iW = W - mg.left - mg.right;
  const iH = H - mg.top  - mg.bottom;
  const xD = [35, 205], yD = [235, 615];

  function scX(v) { return mg.left + (v - xD[0]) / (xD[1] - xD[0]) * iW; }
  function scY(v) { return mg.top  + (1 - (v - yD[0]) / (yD[1] - yD[0])) * iH; }
  function clampY(v) { return Math.max(yD[0], Math.min(yD[1], v)); }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#f9f8f5";
    ctx.fillRect(0, 0, W, H);

    // Cuadrícula
    ctx.strokeStyle = "#ddd"; ctx.lineWidth = 1;
    [60,80,100,120,140,160,180,200].forEach(t => {
      ctx.beginPath(); ctx.moveTo(scX(t), mg.top); ctx.lineTo(scX(t), mg.top + iH); ctx.stroke();
      ctx.fillStyle = "#888"; ctx.font = "11px system-ui"; ctx.textAlign = "center";
      ctx.fillText(t, scX(t), mg.top + iH + 16);
    });
    [300,350,400,450,500,550,600].forEach(t => {
      ctx.beginPath(); ctx.moveTo(mg.left, scY(t)); ctx.lineTo(mg.left + iW, scY(t)); ctx.stroke();
      ctx.fillStyle = "#888"; ctx.font = "11px system-ui"; ctx.textAlign = "right";
      ctx.fillText(t, mg.left - 5, scY(t) + 4);
    });

    // Borde área
    ctx.strokeStyle = "#ccc"; ctx.lineWidth = 1;
    ctx.strokeRect(mg.left, mg.top, iW, iH);

    // Etiquetas ejes
    ctx.fillStyle = "#555"; ctx.font = "12px system-ui"; ctx.textAlign = "center";
    ctx.fillText("Fertilización (kg N/ha)", mg.left + iW / 2, H - 6);
    ctx.save();
    ctx.translate(13, mg.top + iH / 2); ctx.rotate(-Math.PI / 2);
    ctx.fillText("Rendimiento (kg/ha)", 0, 0);
    ctx.restore();

    if (!currentCloud) return;

    const pts = currentCloud;
    const n   = pts.length;
    const mx  = pts.reduce((s, p) => s + p.x, 0) / n;
    const my  = pts.reduce((s, p) => s + p.y, 0) / n;
    const sx  = Math.sqrt(pts.reduce((s, p) => s + (p.x - mx) ** 2, 0) / n);
    const sy  = Math.sqrt(pts.reduce((s, p) => s + (p.y - my) ** 2, 0) / n);

    // Línea de estimación del usuario
    const g = parseFloat(slider.value);
    const slope = g * (sy / (sx + 1e-9));
    ctx.beginPath();
    ctx.setLineDash([7, 4]);
    ctx.strokeStyle = "#006494"; ctx.lineWidth = 2.2;
    ctx.moveTo(scX(xD[0]), scY(clampY(my + slope * (xD[0] - mx))));
    ctx.lineTo(scX(xD[1]), scY(clampY(my + slope * (xD[1] - mx))));
    ctx.stroke();
    ctx.setLineDash([]);

    // Puntos
    ctx.fillStyle = "#01696f";
    pts.forEach(p => {
      ctx.beginPath();
      ctx.arc(scX(p.x), scY(p.y), 4.5, 0, 2 * Math.PI);
      ctx.globalAlpha = 0.65; ctx.fill(); ctx.globalAlpha = 1;
    });

    // Etiqueta estimación
    const gStr = (g >= 0 ? "+" : "") + g.toFixed(2);
    ctx.fillStyle = "#006494"; ctx.font = "bold 14px system-ui"; ctx.textAlign = "right";
    ctx.fillText("Mi r = " + gStr, W - mg.right - 4, mg.top + 18);
  }

  // ── Nueva nube ───────────────────────────────────────────────────────────────
  function nuevaNube() {
    const rhoTarget = STEPS[Math.floor(Math.random() * STEPS.length)];
    currentCloud    = generateCloud(rhoTarget, 60);
    currentRhoReal  = Math.round(pearson(currentCloud) * 100) / 100;
    slider.value    = "0";
    sliderVal.textContent = "0.00";
    panelRes.style.background = "#f3f0ec";
    panelRes.style.color      = "#7a7974";
    panelRes.innerHTML = "Ajusta el slider y pulsa <strong>✅ Verificar</strong> para ver tu puntuación.";
    draw();
  }

  // ── Verificar (solo aquí se toca el historial) ───────────────────────────────
  function verificar() {
    if (!currentCloud) { alert("Genera primero una nube con 🎲"); return; }

    const g    = Math.round(parseFloat(slider.value) * 100) / 100;
    const diff = Math.round(Math.abs(g - currentRhoReal) * 100) / 100;

    const [emoji, msg, color, bg] =
      diff <= 0.05 ? ["🏆","¡Excelente! Muy cerca.",    "#437a22","#d4dfcc"] :
      diff <= 0.10 ? ["🎯","¡Muy bien! Casi exacto.",   "#01696f","#cedcd8"] :
      diff <= 0.20 ? ["👍","Bien. Diferencia aceptable.","#d19900","#e9e0c6"] :
      diff <= 0.35 ? ["📉","Cerca, pero puedes mejorar.","#da7101","#e7d7c4"] :
                     ["❌","Sigue practicando.",         "#a12c7b","#e0ced7"];

    // Panel de resultado
    panelRes.style.background = bg;
    panelRes.style.color      = color;
    panelRes.innerHTML =
      `<div style="font-size:18px;font-weight:700;margin-bottom:4px;">${emoji} ${msg}</div>
       <div style="font-size:14px;display:flex;gap:20px;flex-wrap:wrap;">
         <span>r real = <strong>${currentRhoReal.toFixed(2)}</strong></span>
         <span>Tu estimación = <strong>${g.toFixed(2)}</strong></span>
         <span>Diferencia = <strong>${diff.toFixed(2)}</strong></span>
       </div>
       <div style="margin-top:6px;font-size:12px;opacity:0.8;">
         Pulsa 🎲 <strong>Nueva nube</strong> para continuar.
       </div>`;

    // Agregar al historial (una sola vez, aquí)
    historial.push({ n: historial.length + 1, rReal: currentRhoReal, guess: g, diff, emoji, bg });
    renderHistorial();
  }

  // ── Renderizar historial ─────────────────────────────────────────────────────
  function renderHistorial() {
    histWrap.style.display = "block";
    tablaBody.innerHTML = historial.map(h =>
      `<tr style="background:${h.bg}">
        <td style="padding:5px 10px;text-align:center">${h.n}</td>
        <td style="padding:5px 10px;text-align:center;font-weight:700">${h.rReal.toFixed(2)}</td>
        <td style="padding:5px 10px;text-align:center">${h.guess.toFixed(2)}</td>
        <td style="padding:5px 10px;text-align:center">${h.diff.toFixed(2)}</td>
        <td style="padding:5px 10px;text-align:center">${h.emoji}</td>
      </tr>`
    ).join("");

    const avg = (historial.reduce((s, h) => s + h.diff, 0) / historial.length).toFixed(2);
    resStats.innerHTML =
      `Diferencia promedio: <strong>${avg}</strong> &nbsp;|&nbsp;
       Intentos: <strong>${historial.length}</strong>`;
  }

  // ── Eventos ──────────────────────────────────────────────────────────────────
  slider.addEventListener("input", () => {
    const v = parseFloat(slider.value);
    sliderVal.textContent = (v >= 0 ? "+" : "") + v.toFixed(2);
    draw();
  });

  btnNuevo.addEventListener("click", nuevaNube);
